using System;
using UnityEngine;
namespace BWVR {
public enum VillageResource { Wood, Wheat, Resin }
[Serializable] public sealed class ResourceSource {
 public bool expansionPlot,farmPrepared;public Vector3 farmPosition;public string id,treeId;public VillageResource kind;public float remaining=12;public bool felled,growing;public float growth;public int plantings,regrown;
}
[Serializable] public sealed class ResourceCargo {
 public string source;public VillageResource kind;public float amount;
 public void Clear(){source=null;amount=0;}
}
[Serializable] public sealed partial class ResourceState {
 public const float WoodCapacity=36,WheatCapacity=48,ResinCapacity=12,WheatSeedCost=1,WheatGrowthTime=180;
 public float seedUsed;
 public int storageUpgrades;public float storageWork,exposedWheat,spoiled;
 public float Limit(VillageResource kind)=>Capacity(kind)+storageUpgrades*(kind==VillageResource.Wood?18:kind==VillageResource.Wheat?24:6);
 public bool NeedsStorage=>storageUpgrades<3&&(storageWork>0||exposedWheat>0||wheat>=Limit(VillageResource.Wheat)*.85f||wood>=Limit(VillageResource.Wood)*.85f||resin>=Limit(VillageResource.Resin)*.85f);
 public bool BuildStorage(float dt){if(!NeedsStorage||wood<6||dt<=0||float.IsNaN(dt)||float.IsInfinity(dt))return false;storageWork=Mathf.Min(20,storageWork+dt);if(storageWork<20)return false;wood-=6;storageUpgrades++;storageWork=0;Shelter();return true;}
 void Shelter(){float saved=Mathf.Min(exposedWheat,Limit(VillageResource.Wheat)-wheat);wheat+=saved;exposedWheat-=saved;}
 public float wood,wheat=6,resin,consumed;public int deliveries;public ResourceSource[] sources=Array.Empty<ResourceSource>();
 public ResourceCargo[] cargo={new ResourceCargo(),new ResourceCargo(),new ResourceCargo()};
 public float Stock(VillageResource kind)=>kind==VillageResource.Wood?wood:kind==VillageResource.Wheat?wheat:resin;
 public static float Capacity(VillageResource kind)=>kind==VillageResource.Wood?WoodCapacity:kind==VillageResource.Wheat?WheatCapacity:ResinCapacity;
 public ResourceSource Find(string id){foreach(var source in sources)if(source.id==id)return source;return null;}
 public ResourceSource Ensure(string id,VillageResource kind){var source=Find(id);if(source!=null)return source;if(sources.Length>=64)return null;source=new ResourceSource{id=id,kind=kind,remaining=YieldLimit(kind)};Array.Resize(ref sources,sources.Length+1);sources[sources.Length-1]=source;return source;}
 public bool DepletedTree(string id){var source=Find(id);if(source==null||source.kind!=VillageResource.Wood||!source.felled||source.growing||source.remaining>.001f||source.plantings>=1000000)return false;foreach(var load in cargo)if(load.amount>0&&load.source==id)return false;return true;}
 public bool Plant(string id){if(!DepletedTree(id))return false;var source=Find(id);source.growing=true;source.remaining=0;source.growth=0;source.plantings++;return true;}
 public bool DepletedField(string id){var source=Find(id);if(source==null||source.kind!=VillageResource.Wheat||(source.expansionPlot&&!source.farmPrepared)||source.growing||source.remaining>.001f||source.plantings>=1000000)return false;foreach(var load in cargo)if(load.amount>0&&load.source==id)return false;return true;}
 public bool Sow(string id){if(wheat<WheatSeedCost||!DepletedField(id))return false;var source=Find(id);wheat-=WheatSeedCost;seedUsed=Mathf.Min(100000000,seedUsed+WheatSeedCost);source.remaining=0;source.growing=true;source.growth=0;source.plantings++;return true;}
 public bool Grow(string id,float dt){var source=Find(id);if(source==null||!source.growing||(source.kind!=VillageResource.Wood&&source.kind!=VillageResource.Wheat)||dt<=0||float.IsNaN(dt)||float.IsInfinity(dt))return false;source.growth=Mathf.Min(1,source.growth+dt/(source.kind==VillageResource.Wheat?WheatGrowthTime:300));if(source.growth<1)return false;source.growing=false;source.felled=false;source.remaining=12;source.regrown++;return true;}
 public static float YieldLimit(VillageResource kind)=>kind==VillageResource.Resin?4:12;
 public static float LoadLimit(VillageResource kind)=>kind==VillageResource.Resin?2:3;
 public ResourceSource EnsureResin(string treeId){var tree=Find(treeId);if(tree==null||tree.kind!=VillageResource.Wood||treeId.Length>154)return null;var source=Ensure("resin-"+treeId,VillageResource.Resin);if(source==null||source.kind!=VillageResource.Resin)return null;source.treeId=treeId;if(tree.felled||tree.growing)source.remaining=0;return source;}
 bool LivingResin(ResourceSource source){var tree=Find(source.treeId);return tree!=null&&tree.kind==VillageResource.Wood&&!tree.felled&&!tree.growing;}
 public void RenewResin(string id,float dt,bool available){var source=Find(id);if(!available||source==null||source.kind!=VillageResource.Resin||!LivingResin(source)||dt<=0||float.IsNaN(dt)||float.IsInfinity(dt))return;float pending=0;foreach(var load in cargo)if(load.source==id)pending+=load.amount;source.remaining=Mathf.Min(Mathf.Max(0,4-pending),source.remaining+dt/90);}
 public float Harvest(int actor,string sourceId,float amount){var source=Find(sourceId);if(source==null||(source.expansionPlot&&!source.farmPrepared)||source.growing||cargo[actor].amount>0||float.IsNaN(amount)||float.IsInfinity(amount))return 0;if(source.kind==VillageResource.Resin&&!LivingResin(source))return 0;if(source.kind==VillageResource.Wood)foreach(var load in cargo)if(load.amount>0&&load.kind==VillageResource.Resin&&Find(load.source)?.treeId==source.id)return 0;amount=Mathf.Min(LoadLimit(source.kind),Mathf.Max(0,amount),source.remaining);if(amount<=0)return 0;source.remaining-=amount;if(source.kind==VillageResource.Wood){source.felled=true;foreach(var linked in sources)if(linked.kind==VillageResource.Resin&&linked.treeId==source.id)linked.remaining=0;}cargo[actor].source=sourceId;cargo[actor].kind=source.kind;cargo[actor].amount=amount;return amount;}
 public float Deposit(int actor){var load=cargo[actor];if(load.amount<=0)return 0;float accepted=Mathf.Min(load.amount,Mathf.Max(0,Limit(load.kind)-Stock(load.kind)));if(load.kind==VillageResource.Wood)wood+=accepted;else if(load.kind==VillageResource.Resin)resin+=accepted;else{wheat+=accepted;float outside=Mathf.Min(load.amount-accepted,24-exposedWheat);exposedWheat+=outside;accepted+=outside;}var source=Find(load.source);if(source!=null)source.remaining=Mathf.Min(YieldLimit(source.kind),source.remaining+load.amount-accepted);load.Clear();if(accepted>0)deliveries=Math.Min(1000000,deliveries+1);return accepted;}
 public void Recover(int actor){var load=cargo[actor];var source=Find(load.source);if(source!=null)source.remaining=Mathf.Min(YieldLimit(source.kind),source.remaining+load.amount);load.Clear();}
 public void Consume(float dt,int people,float reservedSeed=0,float rain=0){if(float.IsNaN(rain)||float.IsInfinity(rain))return;if(dt<=0||float.IsNaN(dt)||float.IsInfinity(dt)||float.IsNaN(reservedSeed)||float.IsInfinity(reservedSeed))return;float eaten=Mathf.Min(Mathf.Max(0,wheat-Mathf.Max(0,reservedSeed)),dt*Mathf.Clamp(people,0,6)/90f);wheat-=eaten;consumed=Mathf.Min(100000000,consumed+eaten);Shelter();float lost=Mathf.Min(exposedWheat,dt*.025f*(1+3*Mathf.Clamp01(rain)));exposedWheat-=lost;spoiled=Mathf.Min(100000000,spoiled+lost);}
 static bool GrowthValid(ResourceSource source){
  if(!HybridState.Number(source.growth,0,1)||source.plantings<0||source.plantings>1000000||source.regrown<0||source.regrown>source.plantings||source.plantings!=source.regrown+(source.growing?1:0))return false;
  if(source.kind==VillageResource.Resin)return !source.growing&&source.growth==0&&source.plantings==0;
  if(source.kind==VillageResource.Wheat&&source.growth>0&&source.plantings==0)return false;
  return !source.growing||(source.remaining==0&&source.growth<1&&(source.kind==VillageResource.Wood?source.felled:!source.felled));
 }
 public bool Valid(){if(!HybridState.Number(seedUsed,0,100000000)||!HybridState.Number(resin,0,Limit(VillageResource.Resin))||storageUpgrades<0||storageUpgrades>3||!HybridState.Number(storageWork,0,20)||!HybridState.Number(exposedWheat,0,24)||!HybridState.Number(spoiled,0,100000000)||!HybridState.Number(wood,0,Limit(VillageResource.Wood))||!HybridState.Number(wheat,0,Limit(VillageResource.Wheat))||!HybridState.Number(consumed,0,100000000)||deliveries<0||deliveries>1000000||sources==null||sources.Length>64||cargo==null||cargo.Length!=3)return false;if(!FarmsValid())return false;var ids=new System.Collections.Generic.HashSet<string>();foreach(var source in sources)if(source==null||string.IsNullOrEmpty(source.id)||source.id.Length>160||!ids.Add(source.id)||!Enum.IsDefined(typeof(VillageResource),source.kind)||!HybridState.Number(source.remaining,0,YieldLimit(source.kind))||(source.felled&&source.kind!=VillageResource.Wood)||!GrowthValid(source))return false;foreach(var source in sources){if(source.kind==VillageResource.Resin){var tree=Find(source.treeId);if(tree==null||tree.kind!=VillageResource.Wood||((tree.felled||tree.growing)&&source.remaining>0))return false;}else if(!string.IsNullOrEmpty(source.treeId))return false;}var loads=new System.Collections.Generic.Dictionary<string,float>();foreach(var load in cargo){if(load==null||!Enum.IsDefined(typeof(VillageResource),load.kind)||!HybridState.Number(load.amount,0,LoadLimit(load.kind)))return false;if(load.amount<=0)continue;var source=Find(load.source);if(source==null||source.growing||source.kind!=load.kind||(source.kind==VillageResource.Resin&&!LivingResin(source)))return false;loads.TryGetValue(source.id,out float total);loads[source.id]=total+load.amount;if(source.remaining+loads[source.id]>YieldLimit(source.kind)+.001f)return false;}return true;}
}
}
